    cells = {}
    for c in row.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
        ref = c.get('r')
        vnode = c.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v')
