    rows.append(cells)

all_refs = sorted({r for cells in rows for r in cells})
for i, cells in enumerate(rows, start=1):
    print('row' + str(i) + ': ' + ' | '.join(cells.get(r, '') for r in all_refs))

total = 0.0
for cells in rows:
    for val in cells.values():
        try:
            total += float(val)
        except ValueError:
            pass
print('TOTAL_NUMERIC=' + repr(total))

